public RefreshFrequency xds()
{
    METIndustryKeyIdTablePolicyTmp           metIndustryKeyTablePolicyTmp;
    METUserSecurityGroupList                 metUserSecurityGroupList;
    METUserSecurityMETIndustryKeyTableList   metUserSecurityMETIndustryKeyTableList;
    METIndustryKeyTable                      metIndustryKeyTable;

    Unchecked(Uncheck::XDS)
    {
        while select crosscompany RecId, DataAreaId from metIndustryKeyTable
            group by RecId, DataAreaId
            join metUserSecurityMETIndustryKeyTableList
        where metUserSecurityMETIndustryKeyTableList.IndustryKey == metIndustryKeyTable.IndustryKey
            join metUserSecurityGroupList
        where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityMETIndustryKeyTableList.UserSecurityGroupId
        && metUserSecurityGroupList.UserId == curUserId()
        {
            metIndustryKeyTablePolicyTmp.IndustryKey = metIndustryKeyTable.RecId;
            metIndustryKeyTablePolicyTmp.Company = metIndustryKeyTable.DataAreaId;
            metIndustryKeyTablePolicyTmp.insert();
        }
    }

    return RefreshFrequency::PerSession;
}
